      <label
        class="ec-map-mode-selector__option"
        :class="{ 'is-selected': mode === MAP_MODE_PARCEL }"
      >
        <input
          v-model="mode"
          class="ec-map-mode-selector__input"
          type="radio"
          name="ec-map-mode"
          :value="MAP_MODE_PARCEL"
